#include <stdio.h>

int main() {
    int a[] = {-2, 1, -3, 4, -1, 2, 1, -5, 4};
    int n = 9;
    int best = a[0], current = a[0];
    for (int i = 1; i < n; i++) {
        int extend = current + a[i];
        current = extend > a[i] ? extend : a[i];
        if (current > best) best = current;
    }
    printf("Maximum subarray sum: %d\n", best);
    return 0;
}
